-- Lot 205 : payloads 121 a 150 sur 1299.
--
-- Chaque commande recoit un texte propre a ChatGPT, a Claude et a Gemini.
-- Rien n'est supprime : l'ancienne version quitte le courant et reste lisible
-- dans l'historique, ce qui suffit a revenir en arriere.

drop table if exists lot_v5_payloads;
create temporary table lot_v5_payloads as
select * from jsonb_to_recordset($raccourcia$[{"ref":"RCI-IMG-138","moteur":"chatgpt","payload":"[RaccourcIA — /safetyvisual]\n\nMISSION\nTransformer des règles de sécurité en affiche pédagogique. Reprends uniquement les consignes fournies, hiérarchise actions et interdictions et conserve les pictogrammes de référence. Le résultat n’est pas une certification réglementaire.\n\nDÉCISION\nAnalyse le message, l’historique utile et chaque image jointe. Si un outil de génération ou d’édition d’image est disponible, utilise-le avec les références exactes. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Consignes de sécurité visuelles » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Reprends uniquement les consignes fournies, hiérarchise actions et interdictions et conserve les pictogrammes de référence. Le résultat n’est pas une certification réglementaire. Le format par défaut est 16:9 en haute définition; adapte-le au canal explicite. Si du texte est nécessaire, utilise le texte exact fourni ou demande uniquement l’information manquante. Si le texte peut être créé, propose une version courte et exacte; sinon choisis le mode sans texte.\n\nPRÉSERVER\nConserve l’enveloppe, les proportions, l’orientation et les repères vérifiés du sujet; distingue clairement représentation réelle et conceptuelle.\n\nÉVITER\nÉvite composants inventés présentés comme réels, cotes déduites sans échelle, légendes illisibles, perspective impossible et fausse précision. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique technique, logo ou texte officiel. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Avant de livrer, vérifie silencieusement fidélité du sujet, proportions, perspective, lumière, ombres, anatomie, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. fidélité; impact; lisibilité; composition; lumière; perspective; matière; texte; absence d’artefacts Si aucun outil image n’est accessible, fournis le prompt final prêt à exécuter et indique en une phrase que l’image n’a pas été générée.","sha256":"d53072d2e4c3acfda9dc612505bdf911226c201e91e5f7b458b489bf8abbf415"},{"ref":"RCI-IMG-138","moteur":"claude","payload":"[RaccourcIA — /safetyvisual]\n\nMISSION\nTransformer des règles de sécurité en affiche pédagogique. Reprends uniquement les consignes fournies, hiérarchise actions et interdictions et conserve les pictogrammes de référence. Le résultat n’est pas une certification réglementaire.\n\nDÉCISION\nRepère d’abord les contraintes dans les images et documents, puis consolide-les sans longue reformulation. Vérifie les capacités réellement disponibles avant toute production. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Consignes de sécurité visuelles » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Reprends uniquement les consignes fournies, hiérarchise actions et interdictions et conserve les pictogrammes de référence. Le résultat n’est pas une certification réglementaire. Le format par défaut est 16:9 en haute définition; adapte-le au canal explicite. Si du texte est nécessaire, utilise le texte exact fourni ou demande uniquement l’information manquante. Si le texte peut être créé, propose une version courte et exacte; sinon choisis le mode sans texte.\n\nPRÉSERVER\nConserve l’enveloppe, les proportions, l’orientation et les repères vérifiés du sujet; distingue cl